	info := cp.CheckpointInfo{
		CheckpointID:     sc.Summary.CheckpointID,
		Strategy:         sc.Summary.Strategy,
		CheckpointsCount: sc.Summary.CheckpointsCount,
		FilesTouched:     sc.Summary.FilesTouched,
		SessionCount:     len(sc.Sessions),
	}
