1	// Package fsstore is a reference, test-only persistent checkpoint backend that
2	// stores checkpoints as JSON files on disk. It exists to exercise the pluggable
3	// backend seam (registry + mirror fan-out) with a real, non-git implementation
4	// of the api/checkpoint contract, and to serve as a worked example for new
5	// backends.
6	//
7	// It is deliberately NOT registered by production code: only RegisterForTesting
8	// wires it into the checkpoint registry, so a production binary can never select
9	// it. As a mirror it receives best-effort write fan-out; it intentionally ignores
10	// the git-specific blob-hash fields of the contract and stores transcript bytes
11	// directly, which keeps the example small and makes the contract's remaining
12	// git leakage concrete.
13	package fsstore
14	
15	import (
16		"context"
17		"encoding/json"
18		"fmt"
19		"os"
20		"path/filepath"
21		"sort"
22		"strings"
23		"sync"
24	
25		cp "github.com/entireio/cli/api/checkpoint"
26		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
27		"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
28		"github.com/entireio/cli/redact"
29	)
30	
31	// BackendType is the registry type name for the filesystem reference backend.
32	const BackendType = "fs"
33	
34	// Store is a JSON-file-backed persistent checkpoint store. One file per
35	// checkpoint (<root>/<checkpoint-id>.json) holds the root summary plus all
36	// session content.
37	type Store struct {
38		root string
39		mu   sync.Mutex
40	}
41	
42	// New constructs a filesystem store rooted at dir.
43	func New(dir string) *Store {
44		return &Store{root: dir}
45	}
46	
47	type storedSession struct {
48		SessionID  string      `json:"session_id"`
49		Metadata   cp.Metadata `json:"metadata"`
50		Transcript []byte      `json:"transcript,omitempty"`
51		Prompts    string      `json:"prompts,omitempty"`
52	}
53	
54	type storedCheckpoint struct {
55		Summary  cp.CheckpointSummary `json:"summary"`
56		Sessions []storedSession      `json:"sessions"`
57	}
58	
59	var (
60		_ cp.PersistentStore = (*Store)(nil)
61		_ cp.Writer          = (*Store)(nil)
62	)
63	
64	func (s *Store) path(checkpointID id.CheckpointID) string {
65		return filepath.Join(s.root, string(checkpointID)+".json")
66	}
67	
68	// load reads the stored checkpoint, returning (nil, nil) when it does not exist.
69	func (s *Store) load(checkpointID id.CheckpointID) (*storedCheckpoint, error) {
70		data, err := os.ReadFile(s.path(checkpointID))
71		if err != nil {
72			if os.IsNotExist(err) {
73				return nil, nil //nolint:nilnil // absent checkpoint, not an error
74			}
75			return nil, fmt.Errorf("fsstore: read %s: %w", checkpointID, err)
76		}
77		var sc storedCheckpoint
78		if err := json.Unmarshal(data, &sc); err != nil {
79			return nil, fmt.Errorf("fsstore: parse %s: %w", checkpointID, err)
80		}
81		return &sc, nil
82	}
83	
84	func (s *Store) save(sc *storedCheckpoint) error {
85		if err := os.MkdirAll(s.root, 0o755); err != nil {
86			return fmt.Errorf("fsstore: create root %s: %w", s.root, err)
87		}
88		data, err := json.MarshalIndent(sc, "", "  ")
89		if err != nil {
90			return fmt.Errorf("fsstore: encode %s: %w", sc.Summary.CheckpointID, err)
91		}
92		if err := os.WriteFile(s.path(sc.Summary.CheckpointID), data, 0o644); err != nil { //nolint:gosec // reference test backend
93			return fmt.Errorf("fsstore: write %s: %w", sc.Summary.CheckpointID, err)
94		}
95		return nil
96	}
97	
98	// Write dispatches on the request type, mirroring the git store's Write.
99	func (s *Store) Write(_ context.Context, req cp.WriteRequest) error {
100		s.mu.Lock()
101		defer s.mu.Unlock()
102	
103		switch r := req.(type) {
104		case cp.Session:
105			return s.writeSession(cp.WriteOptions(r))
106		case cp.SessionTranscript:
107			return s.backfillTranscript(cp.UpdateOptions(r))
108		case cp.SessionSummary:
109			return s.writeSessionSummary(r)
110		case cp.CheckpointAttribution:
111			return s.writeAttribution(r)
112		default:
113			return fmt.Errorf("fsstore: unsupported write request %T", req)
114		}
115	}
116	
117	func (s *Store) writeSession(opts cp.WriteOptions) error {
118		sc, err := s.load(opts.CheckpointID)
119		if err != nil {
120			return err
121		}
122		if sc == nil {
123			sc = &storedCheckpoint{Summary: cp.CheckpointSummary{CheckpointID: opts.CheckpointID}}
124		}
125	
126		session := storedSession{
127			SessionID:  opts.SessionID,
128			Metadata:   metadataFromWriteOptions(opts),
129			Transcript: opts.Transcript.Bytes(),
130			Prompts:    redact.String(strings.Join(opts.Prompts, checkpoint.PromptSeparator)),
131		}
132		sc.Sessions = upsertSession(sc.Sessions, session)
133		recomputeSummary(sc)
134		return s.save(sc)
135	}
136	
137	func (s *Store) backfillTranscript(opts cp.UpdateOptions) error {
138		sc, err := s.load(opts.CheckpointID)
139		if err != nil {
140			return err
141		}
142		if sc == nil {
143			return fmt.Errorf("fsstore: cannot backfill transcript for unknown checkpoint %s", opts.CheckpointID)
144		}
145		idx := sessionIndexByID(sc.Sessions, opts.SessionID)
146		if idx < 0 {
147			return fmt.Errorf("fsstore: cannot backfill transcript for unknown session %q in %s", opts.SessionID, opts.CheckpointID)
148		}
149		// Replace semantics, but do not clobber sibling fields (matches the git
150		// store's stop-time transcript backfill).
151		sc.Sessions[idx].Transcript = opts.Transcript.Bytes()
152		sc.Sessions[idx].Prompts = redact.String(strings.Join(opts.Prompts, checkpoint.PromptSeparator))
153		if len(opts.SkillEvents) > 0 {
154			sc.Sessions[idx].Metadata.SkillEvents = opts.SkillEvents
155		}
156		return s.save(sc)
157	}
158	
159	func (s *Store) writeSessionSummary(r cp.SessionSummary) error {
160		sc, err := s.load(r.CheckpointID)
161		if err != nil {
162			return err
163		}
164		if sc == nil || len(sc.Sessions) == 0 {
165			return fmt.Errorf("fsstore: cannot set summary for unknown checkpoint %s", r.CheckpointID)
166		}
167		sc.Sessions[len(sc.Sessions)-1].Metadata.Summary = r.Summary
168		return s.save(sc)
169	}
170	
171	func (s *Store) writeAttribution(r cp.CheckpointAttribution) error {
172		sc, err := s.load(r.CheckpointID)
173		if err != nil {
174			return err
175		}
176		if sc == nil {
177			return fmt.Errorf("fsstore: cannot set attribution for unknown checkpoint %s", r.CheckpointID)
178		}
179		sc.Summary.CombinedAttribution = r.Attribution
180		return s.save(sc)
181	}
182	
183	// Read returns the checkpoint summary, or (nil, nil) when absent so the
184	// contract helper normalizes it to ErrCheckpointNotFound.
185	func (s *Store) Read(_ context.Context, checkpointID id.CheckpointID) (*cp.CheckpointSummary, error) {
186		s.mu.Lock()
187		defer s.mu.Unlock()
188		sc, err := s.load(checkpointID)
189		if err != nil || sc == nil {
190			return nil, err
191		}
192		summary := sc.Summary
193		return &summary, nil
194	}
195	
196	func (s *Store) List(_ context.Context) ([]cp.CheckpointInfo, error) {
197		s.mu.Lock()
198		defer s.mu.Unlock()
199	
200		entries, err := os.ReadDir(s.root)
201		if err != nil {
202			if os.IsNotExist(err) {
203				return nil, nil
204			}
205			return nil, fmt.Errorf("fsstore: list %s: %w", s.root, err)
206		}
207	
208		var infos []cp.CheckpointInfo
209		for _, e := range entries {
210			if e.IsDir() || !strings.HasSuffix(e.Name(), ".json") {
211				continue
212			}
213			checkpointID := id.CheckpointID(strings.TrimSuffix(e.Name(), ".json"))
214			sc, err := s.load(checkpointID)
215			if err != nil {
216				return nil, err
217			}
218			if sc == nil {
219				continue
220			}
221			infos = append(infos, infoFromStored(sc))
222		}
223		sort.Slice(infos, func(i, j int) bool { return infos[i].CreatedAt.After(infos[j].CreatedAt) })
224		return infos, nil
225	}
226	
227	func (s *Store) ReadSessionContent(_ context.Context, checkpointID id.CheckpointID, sessionIndex int) (*cp.SessionContent, error) {
228		s.mu.Lock()
229		defer s.mu.Unlock()
230		session, err := s.sessionAt(checkpointID, sessionIndex)
231		if err != nil {
232			return nil, err
233		}
234		return &cp.SessionContent{
235			Metadata:   session.Metadata,
236			Transcript: session.Transcript,
237			Prompts:    session.Prompts,
238		}, nil
239	}

