	if c.Primary.Type == "" {
		return fmt.Errorf("%w: checkpoints.primary.type is required", ErrInvalidCheckpointsConfig)
	}
	for i, m := range c.Mirrors {
		if m.Type == "" {
			return fmt.Errorf("%w: checkpoints.mirrors[%d].type is required", ErrInvalidCheckpointsConfig, i)
		}
	}
	return nil
}

